import 'package:equatable/equatable.dart';

/// `chat` exists here even though no capture flow in this unit ever produces
/// one — `GET /entries` is origin-agnostic and can return a `chat`-sourced
/// entry (e.g., from seed/test data) before RF04/RF10 (the features that
/// will eventually create one) exist, so parsing must recognize all four
/// values rather than throwing on the fourth (research.md R2).
enum EntrySource { manual, audio, photo, chat }

enum PiiStatus { pending, clean, flagged, failed }

enum EmbeddingStatus { pending, ready, failed }

class EntryTag extends Equatable {
  const EntryTag({required this.id, required this.name});

  final String id;
  final String name;

  @override
  List<Object?> get props => [id, name];
}

class PiiSpan extends Equatable {
  const PiiSpan({required this.start, required this.end, required this.type});

  final int start;
  final int end;
  final String type;

  @override
  List<Object?> get props => [start, end, type];
}

/// The full shape of `POST /entries`' response (data-model.md) — every field
/// is `required` in the OpenAPI schema on every response, so none is
/// optional to model here (research.md R8).
class Entry extends Equatable {
  const Entry({
    required this.id,
    required this.content,
    required this.source,
    required this.chatMessageId,
    required this.occurredAt,
    required this.tags,
    required this.piiStatus,
    required this.piiSpans,
    required this.embeddingStatus,
    required this.mediaDurationSeconds,
    required this.serverRevision,
    required this.createdAt,
    required this.updatedAt,
    this.similarity,
  });

  final String id;
  final String content;
  final EntrySource source;
  final String? chatMessageId;
  final DateTime occurredAt;
  final List<EntryTag> tags;
  final PiiStatus piiStatus;
  final List<PiiSpan> piiSpans;
  final EmbeddingStatus embeddingStatus;
  final int? mediaDurationSeconds;
  final int serverRevision;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// 0.0–1.0, only ever non-null when parsed from `entries-search`'s
  /// response (data-model.md).
  final double? similarity;

  @override
  List<Object?> get props => [
    id,
    content,
    source,
    chatMessageId,
    occurredAt,
    tags,
    piiStatus,
    piiSpans,
    embeddingStatus,
    mediaDurationSeconds,
    serverRevision,
    createdAt,
    updatedAt,
    similarity,
  ];
}

import 'package:cerne/core/network/failure.dart';
import 'package:cerne/features/entries/domain/entities/entries_page.dart';
import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:fpdart/fpdart.dart';

/// The shared seam research.md R8 builds because requirements.md §RF10
/// already names it (contracts/entries-repository.md). Registered as a
/// `get_it` `lazySingleton` so [cachedEntries] survives across modal opens
/// (same lifetime pattern as RF03's `VaultRepository`).
abstract class EntriesRepository {
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
  });

  /// FR-011's "local entries store/cache" — every entry this app has ever
  /// successfully fetched or created, backed by on-device persistence so it
  /// survives a restart. `RecordsBloc` reads this back out as the offline
  /// fallback when a fetch fails outright (the PRD's "local read cache",
  /// requirements.md line 50/125).
  List<Entry> get cachedEntries;

  /// `GET /entries` (`entries-list`), paginated newest-occurred-first.
  /// Retries exactly once through `SessionRepository.refresh()` on
  /// `AuthExpiredFailure` before giving up (research.md R4).
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int? limit,
  });

  /// `GET /entries/:id` (`entries-get`). Implemented and tested; no call
  /// site in this unit's UI flow (research.md R7).
  Future<Either<Failure, Entry>> getById(String id);

  /// `GET /entries/search` (`entries-search`) — bounded, no cursor
  /// (FR-005b). Retries exactly once through `SessionRepository.refresh()`
  /// on `AuthExpiredFailure`, same as `list()`/`getById()`.
  Future<Either<Failure, List<Entry>>> search({
    String? q,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int limit = 50,
  });
}

