1	import 'dart:async';
2	
3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/entries/domain/entities/entry.dart';
5	import 'package:cerne/features/entries/domain/repositories/entries_repository.dart';
6	import 'package:cerne/features/records/domain/entities/active_filter_chip.dart';
7	import 'package:cerne/features/records/domain/entities/date_range_filter.dart';
8	import 'package:cerne/features/records/domain/entities/entry_merger.dart';
9	import 'package:cerne/features/records/presentation/bloc/records_event.dart';
10	import 'package:cerne/features/records/presentation/bloc/records_state.dart';
11	import 'package:flutter_bloc/flutter_bloc.dart';
12	import 'package:fpdart/fpdart.dart';
13	
14	/// The one bloc behind "Meus Registros" (contracts/records-bloc.md,
15	/// contracts/records-bloc-extension.md). Depends only on
16	/// `EntriesRepository` — never `SessionRepository`, `ConnectivityChecker`,
17	/// nor `SessionBloc` or any of its event/state types (research.md R4/R5/R11,
18	/// requirements.md RF07's own acceptance criterion).
19	class RecordsBloc extends Bloc<RecordsEvent, RecordsState> {
20	  // The public parameter names (`entriesRepository`/`debounceDuration`) must
21	  // stay underscore-free; an initializing formal would force the private
22	  // field names onto them instead.
23	  RecordsBloc({
24	    required EntriesRepository entriesRepository,
25	    Duration debounceDuration = const Duration(milliseconds: 300),
26	  }) : _entriesRepository = entriesRepository, // ignore: prefer_initializing_formals
27	       _debounceDuration = debounceDuration, // ignore: prefer_initializing_formals
28	       super(const RecordsLoading()) {
29	    on<RecordsStarted>(_onStarted);
30	    on<NextPageRequested>(_onNextPageRequested);
31	    on<PageLoadRetried>(_onPageLoadRetried);
32	    on<RecordsLocalCacheRefreshed>(_onLocalCacheRefreshed);
33	    on<SearchTextChanged>(_onSearchTextChanged);
34	    on<SearchDebounceElapsed>(_onSearchDebounceElapsed);
35	    on<FilterSheetApplied>(_onFilterSheetApplied);
36	    on<FilterChipRemoved>(_onFilterChipRemoved);
37	    on<FiltersAndSearchCleared>(_onFiltersAndSearchCleared);
38	    on<CriteriaLoadRetried>(_onCriteriaLoadRetried);
39	  }
40	
41	  final EntriesRepository _entriesRepository;
42	  final Duration _debounceDuration;
43	  final _reauthController = StreamController<void>.broadcast();
44	
45	  String _query = '';
46	  DateRangeOption _dateRange = DateRangeOption.allTime;
47	  Set<EntrySource> _entryTypes = {};
48	  Timer? _debounceTimer;
49	  int _fetchGeneration = 0;
50	
51	  /// A one-shot side effect, not a state (research.md R5) —
52	  /// `RecordsPage` listens to this to raise the "Sessão expirada" overlay.
53	  Stream<void> get reauthRequired => _reauthController.stream;
54	
55	  Future<void> _onStarted(RecordsStarted event, Emitter<RecordsState> emit) async {
56	    emit(const RecordsLoading());
57	    await _loadFirstPage(emit);
58	  }
59	
60	  Future<void> _onPageLoadRetried(PageLoadRetried event, Emitter<RecordsState> emit) async {
61	    final current = state;
62	    if (current is RecordsLoadFailure) {
63	      emit(const RecordsLoading());
64	      await _loadFirstPage(emit);
65	    } else if (current is RecordsLoaded && current.pageLoadFailure != null) {
66	      await _fetchNextPage(current, emit);
67	    }
68	  }
69	
70	  Future<void> _loadFirstPage(Emitter<RecordsState> emit) async {
71	    final result = await _entriesRepository.list();
72	    result.match(
73	      (failure) {
74	        // Offline (or any other outright) failure on the very first fetch —
75	        // no `RecordsLoaded` yet exists for `_fetchNextPage`/`_fetchForCriteria`
76	        // to simply leave untouched, so the on-device cache (populated by
77	        // any entry this app has ever fetched/created, EntriesLocalCache)
78	        // is the only thing that can stand in for it here. Falls through to
79	        // today's blank `RecordsLoadFailure` only when that cache is itself
80	        // empty (e.g. first-ever launch, already offline).
81	        final cached = EntryMerger.merge(
82	          primary: _entriesRepository.cachedEntries,
83	          secondary: const [],
84	        );
85	        if (failure is AuthExpiredFailure) {
86	          _reauthController.add(null);
87	          if (cached.isEmpty) {
88	            emit(RecordsLoadFailure(failure));
89	          } else {
90	            // Mirrors `_fetchNextPage`'s own rule: reauth has its own
91	            // overlay, so no redundant inline banner here.
92	            emit(RecordsLoaded(entries: cached, nextCursor: null, isLoadingMore: false));
93	          }
94	        } else if (cached.isEmpty) {
95	          emit(RecordsLoadFailure(failure));
96	        } else {
97	          emit(
98	            RecordsLoaded(
99	              entries: cached,
100	              nextCursor: null,
101	              isLoadingMore: false,
102	              pageLoadFailure: failure,
103	            ),
104	          );
105	        }
106	      },
107	      (page) => emit(
108	        RecordsLoaded(
109	          entries: EntryMerger.merge(
110	            primary: page.entries,
111	            secondary: _entriesRepository.cachedEntries,
112	          ),
113	          nextCursor: page.nextCursor,
114	          isLoadingMore: false,
115	        ),
116	      ),
117	    );
118	  }
119	
120	  Future<void> _onNextPageRequested(
121	    NextPageRequested event,
122	    Emitter<RecordsState> emit,
123	  ) async {
124	    final current = state;
125	    if (current is! RecordsLoaded || current.hasReachedEnd || current.isLoadingMore) {
126	      return;
127	    }
128	    await _fetchNextPage(current, emit);
129	  }
130	
131	  Future<void> _fetchNextPage(RecordsLoaded current, Emitter<RecordsState> emit) async {
132	    final generation = ++_fetchGeneration;
133	    emit(current.copyWith(isLoadingMore: true, pageLoadFailure: null));
134	
135	    final bounds = _dateRange.boundsAt(DateTime.now());
136	    final result = await _entriesRepository.list(
137	      cursor: current.nextCursor,
138	      source: _entryTypes.isEmpty ? null : _entryTypes.single,
139	      dateFrom: bounds.from,
140	      dateTo: bounds.to,
141	    );
142	    if (generation != _fetchGeneration) return;
143	
144	    result.match(
145	      (failure) {
146	        if (failure is AuthExpiredFailure) {
147	          _reauthController.add(null);
148	          // entries/cursor unchanged, isLoadingMore resets to false, no
149	          // pageLoadFailure — FR-007's "restored exactly as it was" holds
150	          // by construction.
151	          emit(current.copyWith(isLoadingMore: false, pageLoadFailure: null));
152	        } else {
153	          emit(current.copyWith(isLoadingMore: false, pageLoadFailure: failure));
154	        }
155	      },
156	      (page) => emit(
157	        current.copyWith(
158	          entries: EntryMerger.merge(
159	            primary: current.entries + page.entries,
160	            secondary: _entriesRepository.cachedEntries,
161	          ),
162	          nextCursor: page.nextCursor,
163	          isLoadingMore: false,
164	          pageLoadFailure: null,
165	        ),
166	      ),
167	    );
168	  }
169	
170	  void _onLocalCacheRefreshed(
171	    RecordsLocalCacheRefreshed event,
172	    Emitter<RecordsState> emit,
173	  ) {
174	    final current = state;
175	    if (current is! RecordsLoaded || current.hasAnyActiveCriteria) return;
176	    emit(
177	      current.copyWith(
178	        entries: EntryMerger.merge(
179	          primary: current.entries,
180	          secondary: _entriesRepository.cachedEntries,
181	        ),
182	      ),
183	    );
184	  }
185	
186	  // --- Search text -> debounce -> fetch (FR-001/FR-002, research.md R4/R6) ---
187	
188	  Future<void> _onSearchTextChanged(SearchTextChanged event, Emitter<RecordsState> emit) async {
189	    _debounceTimer?.cancel();
190	    _query = event.text;
191	    if (event.text.isEmpty) {
192	      // Acceptance Scenario 3 / Edge Case: no request for empty text —
193	      // refetch immediately under whatever filters are still active.
194	      await _fetchForCriteria(emit);
195	      return;
196	    }
197	    _debounceTimer = Timer(
198	      _debounceDuration,
199	      () => add(SearchDebounceElapsed(event.text)),
200	    );
201	  }
202	
203	  Future<void> _onSearchDebounceElapsed(
204	    SearchDebounceElapsed event,
205	    Emitter<RecordsState> emit,
206	  ) async {
207	    // Superseded by a newer keystroke/clear that arrived after the timer fired.
208	    if (event.text != _query) return;
209	    await _fetchForCriteria(emit);
210	  }
211	
212	  // --- Filter sheet / chips / clear (FR-003/FR-005/FR-007, research.md R1/R6) ---
213	
214	  Future<void> _onFilterSheetApplied(
215	    FilterSheetApplied event,
216	    Emitter<RecordsState> emit,
217	  ) async {
218	    _dateRange = event.dateRange;
219	    _entryTypes = event.entryTypes;
220	    await _fetchForCriteria(emit);
221	  }
222	
223	  Future<void> _onFilterChipRemoved(
224	    FilterChipRemoved event,
225	    Emitter<RecordsState> emit,
226	  ) async {
227	    switch (event.chip) {
228	      case DateRangeChip():
229	        _dateRange = DateRangeOption.allTime;
230	      case EntryTypeChip(source: final s):
231	        _entryTypes = {..._entryTypes}..remove(s);
232	    }
233	    await _fetchForCriteria(emit);
234	  }
235	
236	  Future<void> _onFiltersAndSearchCleared(
237	    FiltersAndSearchCleared event,
238	    Emitter<RecordsState> emit,
239	  ) async {
240	    _debounceTimer?.cancel();
241	    _query = '';
242	    _dateRange = DateRangeOption.allTime;
243	    _entryTypes = {};
244	    await _fetchForCriteria(emit);
245	  }
246	
247	  Future<void> _onCriteriaLoadRetried(
248	    CriteriaLoadRetried event,
249	    Emitter<RecordsState> emit,
250	  ) async {
251	    // Re-attempts the exact same last-applied criteria (_query/_dateRange/_entryTypes).
252	    await _fetchForCriteria(emit);
253	  }
254	
255	  // --- The core fetch (bounded-vs-paginated branch — research.md R1, generation guard — R6) ---
256	
257	  Future<void> _fetchForCriteria(Emitter<RecordsState> emit) async {
258	    final generation = ++_fetchGeneration;
259	    final current = state;
260	    if (current is RecordsLoaded) {
261	      emit(
262	        current.copyWith(
263	          isApplyingCriteria: true,
264	          searchQuery: _query,
265	          dateRange: _dateRange,
266	          entryTypes: _entryTypes,
267	        ),
268	      );
269	    }
270	    // Nothing to show yet (still on RecordsLoading/RecordsLoadFailure) —
271	    // RecordsStarted's own _loadFirstPage() owns the very first fetch; this
272	    // path is only reachable once a RecordsLoaded exists.
273	
274	    final bounds = _dateRange.boundsAt(DateTime.now());
275	    final result = await _resolveEntries(
276	      query: _query,
277	      dateFrom: bounds.from,
278	      dateTo: bounds.to,
279	      types: _entryTypes,
280	    );
281	    if (generation != _fetchGeneration) return; // superseded — discard silently (FR-005a)
282	
283	    result.match(
284	      (failure) {
285	        final latest = state;
286	        if (latest is! RecordsLoaded) return;
287	        if (failure is AuthExpiredFailure) {
288	          _reauthController.add(null);
289	          // entries/criteria unchanged, no criteriaLoadFailure — same
290	          // "no visible disruption" rule _fetchNextPage already follows.
291	          emit(latest.copyWith(isApplyingCriteria: false));
292	        } else {
293	          emit(latest.copyWith(isApplyingCriteria: false, criteriaLoadFailure: failure));
294	        }
295	      },
296	      (fetched) {
297	        final latest = state;
298	        if (latest is! RecordsLoaded) return;
299	        emit(
300	          latest.copyWith(
301	            entries: fetched.entries,
302	            nextCursor: fetched.nextCursor, // null whenever bounded (R1)
303	            isApplyingCriteria: false,
304	            criteriaLoadFailure: null,
305	          ),
306	        );
307	      },
308	    );
309	  }
310	
311	  /// Picks the shape (single call+cursor vs. bounded fan-out-and-merge) per
312	  /// research.md R1.
313	  Future<Either<Failure, ({List<Entry> entries, String? nextCursor})>> _resolveEntries({
314	    required String query,
315	    required DateTime? dateFrom,
316	    required DateTime? dateTo,
317	    required Set<EntrySource> types,
318	  }) async {
319	    if (types.length <= 1) {
320	      final source = types.isEmpty ? null : types.single;
321	      if (query.isNotEmpty) {
322	        final result = await _entriesRepository.search(
323	          q: query,
324	          source: source,
325	          dateFrom: dateFrom,
326	          dateTo: dateTo,
327	        );
328	        return result.map((entries) => (entries: entries, nextCursor: null));
329	      }
330	      final result = await _entriesRepository.list(
331	        source: source,
332	        dateFrom: dateFrom,
333	        dateTo: dateTo,
334	      );
335	      return result.map((page) => (entries: page.entries, nextCursor: page.nextCursor));
336	    }
337	
338	    // 2+ entry types — bounded fan-out, one call per type (research.md R1).
339	    final calls = types.map(
340	      (source) => query.isNotEmpty
341	          ? _entriesRepository.search(q: query, source: source, dateFrom: dateFrom, dateTo: dateTo)
342	          : _entriesRepository
343	                .list(source: source, dateFrom: dateFrom, dateTo: dateTo, limit: 50)
344	                .then((r) => r.map((page) => page.entries)),
345	    );
346	    final results = await Future.wait(calls);
347	    for (final r in results) {
348	      if (r.isLeft()) {
349	        return r.map((_) => (entries: <Entry>[], nextCursor: null));
350	      }
351	    }
352	    final merged = EntryMerger.mergeMany(
353	      sources: [for (final r in results) r.getOrElse((_) => [])],
354	      byRelevance: query.isNotEmpty,
355	    );
356	    return Right((entries: merged, nextCursor: null));
357	  }
358	
359	  @override
360	  Future<void> close() {
361	    _debounceTimer?.cancel();
362	    unawaited(_reauthController.close());
363	    return super.close();
364	  }
365	}
