  path: AppRoutes.home,
  builder: (context, state) => MultiBlocProvider(
    providers: [
      BlocProvider<ChatBloc>(create: (_) => getIt<ChatBloc>()..add(const ChatStarted())),
      BlocProvider<ChatSessionsBloc>(create: (_) => getIt<ChatSessionsBloc>()),
