            ChatReady(
              sessionId: sessionId,
              messages: const [],
              isOffline: isOffline,
              awaitingResponse: false,
              loadFailure: failure,
            ),
          );
        } else {
          emit(
            ChatReady(
              sessionId: sessionId,
              messages: cached,
              isOffline: isOffline,
              awaitingResponse: false,
            ),
          );
        }
      },
      (messages) async {
        await _chatRepository.setLastActiveSessionId(sessionId);
        emit(
          ChatReady(
            sessionId: sessionId,
            messages: messages,
            isOffline: isOffline,
            awaitingResponse: false,
          ),
        );
      },
    );
  }

