          ContextReceived() => latest,
          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
          StreamDone(
            assistantMessageId: final id,
            content: final c,
            createdAt: final t,
          ) =>
            _completeMessage(latest, id, c, t).copyWith(awaitingResponse: false),
        });
      },
    );
