    final updated = [
      for (final m in current.messages)
        if (m.id == assistantId) _withContent(m, m.content + delta) else m,
    ];
    return current.copyWith(messages: updated);
  }

  ChatReady _completeMessage(
    ChatReady current,
    String assistantId,
    String content,
    DateTime createdAt,
  ) {
    final updated = [
      for (final m in current.messages)
        if (m.id == assistantId)
