        }
      },
      (page) => emit(
        current.copyWith(
          sessions: [...current.sessions, ...page.sessions],
          nextCursor: page.nextCursor,
          isLoadingMore: false,
          pageLoadFailure: null,
        ),
      ),
    );
  }

  Future<void> _onPageLoadRetried(
    SessionsPageLoadRetried event,
    Emitter<ChatSessionsState> emit,
  ) async {
