            .having((s) => s.sessions.map((e) => e.id), 'session ids', ['s1', 's2'])
            .having((s) => s.nextCursor, 'nextCursor', isNull)
            .having((s) => s.isLoadingMore, 'isLoadingMore', false),
      ],
    );

