  role: role,
  content: content,
  seq: 0,
  status: status,
  retryCount: 0,
  createdAt: DateTime(2026, 1, 1, 10, 30),
);

Future<void> pumpBubble(
  WidgetTester tester,
  ChatMessage message, {
  VoidCallback? onRetryTap,
}) {
  return tester.pumpWidget(
    MaterialApp(
      home: Scaffold(
        body: ChatMessageBubble(message: message, onRetryTap: onRetryTap),
      ),
    ),
  );
}

void main() {
  testWidgets('a streaming message renders a progress indicator and is not tappable', (
    tester,
  ) async {
    var tapped = false;
    await pumpBubble(
      tester,
      _buildMessage(status: ChatMessageStatus.streaming),
      onRetryTap: () => tapped = true,
    );

    expect(find.byType(CircularProgressIndicator), findsOneWidget);

