  SessionBloc({
    required this._checkSessionUseCase,
    required this._sessionRepository,
  })  : super(SessionStatus.checking) {
    on<AppStarted>(_onAppStarted);
    on<AuthExpiredDetected>(_onAuthExpiredDetected);
